    def __init__(self):
        self.students = []
        self.students_registration_classes = {}

    def register_student(self, new_student):
        name = new_student.get_name()
        major = new_student.get_major()
        for student in self.students:
            if student.get_name() == name:
                return 0
        self.students.append(Student(name, major))
        return 1

    def register_class(self, student_name, class_name):
        # operator[] default-inserts an empty vector for a missing key
        classes = self.students_registration_classes.setdefault(student_name, [])
        if class_name not in classes:
            classes.append(class_name)
        # C++ returns the vector by value, so return a copy (no aliasing of internal state)
        return list(classes)

    def get_students_by_major(self, major):
        student_list = []
        for student in self.students:
            if student.get_major() == major:
                student_list.append(student.get_name())
        return student_list

    def get_all_major(self):
        majors = set()
        for student in self.students:
            majors.add(student.get_major())
        # std::set iterates in sorted order
        return sorted(majors)

    def get_most_popular_class_in_major(self, major):
        class_count = {}

        for student in self.students:
            if student.get_major() == major:
                classes = self.students_registration_classes.get(student.get_name())
                if classes is not None:
                    for class_name in classes:
                        class_count[class_name] = class_count.get(class_name, 0) + 1

        most_popular_class = ""
        max_count = 0
        for class_name, count in class_count.items():
            if count > max_count:
                most_popular_class = class_name
                max_count = count

        return most_popular_class
