        for i in range(1, n + 1):
            total += ArrangementCalculator.count(n, i)
        return total

    def _permutations_recursive(
        self,
        current: List[str],
        remaining: List[str],
        m: int,
        result: List[List[str]],
    ) -> None:
        if len(current) == m:
            result.append(current)
        else:
            for i in range(len(remaining)):
                new_current = current + [remaining[i]]
                new_remaining = remaining[:i] + remaining[i + 1:]
                self._permutations_recursive(new_current, new_remaining, m, result)

    def select(self, m: int = -1) -> List[List[str]]:
        result: List[List[str]] = []
        if m == -1:
            m = len(self._datas)

        current: List[str] = []
        remaining: List[str] = list(self._datas)

        self._permutations_recursive(current, remaining, m, result)

        return result

    def select_all(self) -> List[List[str]]:
        result: List[List[str]] = []
        for i in range(1, len(self._datas) + 1):
            partial_result = self.select(i)
            result.extend(partial_result)
        return result

    @staticmethod
    def factorial(n: int) -> int:
        result = 1
        for i in range(2, n + 1):
            result *= i
        return result
