                return Authorization()

            jwt_timestamp = int(match.group(1))
            # C++ sets failbit when the parsed value overflows time_t
            # (64-bit on the usual platforms).
            if not (-(2 ** 63) <= jwt_timestamp <= 2 ** 63 - 1):
                return Authorization()

            now = int(time.time())
            if now - jwt_timestamp >= 3 * 24 * 60 * 60:
                return Authorization()

