        if not octet or len(octet) > 3:
            return False
        for c in octet:
            # explicit ASCII-digit check, matching C's isdigit() in the
            # "C" locale (str.isdigit() would also accept Unicode digits)
            if not ('0' <= c <= '9'):
                return False
        value = int(octet)
        return 0 <= value <= 255

