        if (expression[0] < '0' || expression[0] > '9')
        {
            if(expression[0] != '(')
                throw(false);
        }
        int kkk = expression.size() - 1;
        if (expression[kkk] < '0' || expression[kkk] > '9')
        {
            if (expression[kkk] != ')')
                throw(false);
        }
        Calculator calculator;
        double ans = calculator.calculate(expression);

        if (ans == 24.0)
        {
            return true;
        }
        else return false;
    }
    catch (...) {
        return false;
    }
}

