```python
import os


def _java_split(s, sep):
    """Mimic Java's String.split(regex) for a literal separator:
    trailing empty strings are discarded (limit == 0 behaviour)."""
    if sep not in s:
        return [s]
    parts = s.split(sep)
    while parts and parts[-1] == '':
        parts.pop()
    return parts


class CSVProcessor:

    def readCSV(self, fileName, title, data):
        with open(fileName) as reader:
            line = reader.readline()
            if line != '':
                # Java's readLine() strips the line terminator; Python's
                # universal-newline mode leaves a trailing '\n'.
                title.extend(_java_split(line.rstrip('\n'), ','))
                for lineData in reader:
                    data.append(_java_split(lineData.rstrip('\n'), ','))

    def writeCSV(self, *args):
        # Java has two overloads: writeCSV(title, data, fileName)
        # and writeCSV(data, fileName).
        if len(args) == 3:
            title, data, fileName = args
        elif len(args) == 2:
            title, data, fileName = None, args[0], args[1]
        else:
            raise TypeError(
                "writeCSV() takes 2 or 3 arguments ({} given)".format(len(args)))

        try:
            with open(fileName, 'w') as writer:
                if title is not None:
                    writer.write(','.join(title))
                    writer.write('\n')  # BufferedWriter.newLine()
                for row in data:
                    writer.write(','.join(row))
                    writer.write('\n')
                return 1
        except OSError:  # IOException
            return 0

    def processCSVData(self, N, saveFileName):
        title = []
        data = []
        self.readCSV(saveFileName, title, data)

        columnData = []
        for row in data:
            if N < len(row):
                if N < 0:
                    # Java's List.get(N) throws IndexOutOfBoundsException
                    # for negative indices; Python would wrap around.
                    raise IndexError("Index: {}, Size: {}".format(N, len(row)))
                columnData.append(row[N].upper())

        newData = [columnData]

        return self.writeCSV(
            title, newData, _java_split(saveFileName, ".")[0] + "_process.csv")
```

