import math


def _int32(value):
    """Wrap an integer to Java's 32-bit signed int semantics."""
    value &= 0xFFFFFFFF
    if value >= 0x80000000:
        value -= 0x100000000
    return value


def _java_div(a, b):
    """Java integer division: truncates toward zero (Python // floors)."""
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return _int32(q) if q > 0x7FFFFFFF else q


class CombinationCalculator:
    def __init__(self, datas):
        self.datas = datas

    @staticmethod
    def count(n, m):
        if m == 0 or n == m:
            return 1
        return _java_div(
            CombinationCalculator._factorial(n),
            _int32(CombinationCalculator._factorial(n - m) * CombinationCalculator._factorial(m)),
        )

    @staticmethod
    def _factorial(x):
        result = 1
        for i in range(1, x + 1):
            result = _int32(result * i)
        return result

    @staticmethod
    def countAll(n):
        if n < 0 or n > 63:
            return float('nan')
        if n == 63:
            return float('inf')
        # Java: (1 << n) is an int shift; the shift distance is masked to 5 bits.
        shifted = _int32(1 << (n & 31))
        return float(_int32(shifted - 1))

    def select(self, m):
        result = []
        self._select(0, [], 0, result, m)
        return result

    def selectAll(self):
        result = []
        for i in range(1, len(self.datas) + 1):
            result.extend(self.select(i))
        return result

    def _select(self, data_index, result_list, result_index, result, m):
        if result_index == m:
            result.append(list(result_list))
            return
        for i in range(data_index, len(self.datas) - (m - result_index) + 1):
            result_list.insert(result_index, self.datas[i])
            self._select(i + 1, result_list, result_index + 1, result, m)
            result_list.pop(result_index)
