        xs = "AND CENTS " + self.transTwo(rstr) + " " if rstr != "" else ""
        if lm.strip() == "":
            return "ZERO ONLY"
        else:
            return lm.strip() + " " + xs + "ONLY"

    def transTwo(self, s):
        s = s.rjust(2).replace(' ', '0')
        if s[0] == '0':
            return self.NUMBER[int(s[1:])]
        elif s[0] == '1':
            return self.NUMBER_TEEN[int(s) - 10]
        elif s[1] == '0':
            return self.NUMBER_TEN[int(s[0:1]) - 1]
        else:
            return self.NUMBER_TEN[int(s[0:1]) - 1] + " " + self.NUMBER[int(s[1:])]

    def transThree(self, s):
        if s[0] == '0':
            return self.transTwo(s[1:])
        elif s[1:] == "00":
            return self.NUMBER[int(s[0:1])] + " HUNDRED"
        else:
            return self.NUMBER[int(s[0:1])] + " HUNDRED AND " + self.transTwo(s[1:])

    def parseMore(self, i):
        return self.NUMBER_MORE[i]
