import re


def _jstr(value):
    """Mimic Java's string conversion: null becomes 'null'."""
    return "null" if value is None else str(value)


def _java_split(s, pattern):
    """Mimic Java's String.split(regex): drop trailing empty strings;
    return [s] unchanged when there is no match."""
    if re.search(pattern, s) is None:
        return [s]
    parts = re.split(pattern, s)
    while parts and parts[-1] == "":
        parts.pop()
    return parts


def select(table, columns, where):
    if columns is None:
        columns = "*"
    if isinstance(columns, str):
        columns = _java_split(columns, r",\s*")

    if len(columns) > 0:
        column_list = ", ".join(_jstr(c) for c in columns)
    else:
        column_list = "*"

    query = "SELECT " + column_list + " FROM " + _jstr(table)

    if where is not None and len(where) > 0:
        conditions = " AND ".join(
            "%s='%s'" % (_jstr(k), _jstr(v)) for k, v in where.items()
        )
        query += " WHERE " + conditions
    return query


def insert(table, data):
    columns = []
    values = []
    for key, value in data.items():
        columns.append(_jstr(key))
        values.append("'" + _jstr(value) + "'")
    return (
