        query += " WHERE " + conditions
    return query


def update(table, data, where):
    assignments = ", ".join(
        "%s='%s'" % (_jstr(k), _jstr(v)) for k, v in data.items()
    )
    query = "UPDATE " + _jstr(table) + " SET " + assignments
