"""Translation of org.example.ZipFileProcessor."""

import logging
import os
import zlib
import zipfile

logger = logging.getLogger("org.example.ZipFileProcessor")

# Exception types that correspond to the IOExceptions raised by the
# java.util.zip / java.nio.file APIs used in the original code.
_IO_ERRORS = (OSError, zipfile.BadZipFile, zlib.error)


class ZipFileProcessor:

    def __init__(self, zip_file_name):
        self.zip_file_path = zip_file_name

    def _read_zip_file(self):
        if not os.path.exists(self.zip_file_path):
            logger.error("Zip file does not exist: %s", os.path.abspath(self.zip_file_path))
            return None
        try:
            return zipfile.ZipFile(self.zip_file_path, "r")
        except _IO_ERRORS:
            logger.error("Failed to read the zip file: %s", os.path.abspath(self.zip_file_path), exc_info=True)
            return None

    def extract_all(self, output_dir):
        zip_file = self._read_zip_file()
        if zip_file is None:
            return False
        try:
            with zip_file:
                if not os.path.exists(output_dir):
                    try:
                        os.makedirs(output_dir, exist_ok=True)
                        logger.info("Created output directory: %s", os.path.abspath(output_dir))
                    except OSError:
                        logger.error("Failed to create output directory: %s", os.path.abspath(output_dir), exc_info=True)
                        return False

                for entry in zip_file.infolist():
                    file_path = os.path.join(output_dir, entry.filename)
                    try:
                        if entry.is_dir():
                            if not os.path.exists(file_path):
                                os.makedirs(file_path, exist_ok=True)
                                logger.info("Created directory: %s", os.path.abspath(file_path))
                        else:
                            with zip_file.open(entry) as in_stream, open(file_path, "wb") as out_stream:
                                while True:
                                    chunk = in_stream.read(1024)
                                    if not chunk:
                                        break
                                    out_stream.write(chunk)
                                logger.info("Extracted file: %s", os.path.abspath(file_path))
                    except _IO_ERRORS:
                        logger.error("Failed to process entry: %s", entry.filename, exc_info=True)
                return True
        except _IO_ERRORS:
            logger.error("Failed to extract files from zip: %s", os.path.abspath(self.zip_file_path), exc_info=True)
            return False

    def extract_file(self, file_name, output_dir):
        file_path = os.path.join(output_dir, file_name)
        parent_dir = os.path.dirname(file_path)
        zip_file = self._read_zip_file()
        if zip_file is None:
            return False
        try:
            with zip_file:
                try:
                    entry = zip_file.getinfo(file_name)
                except KeyError:
                    logger.warning("File not found in zip: %s", file_name)
                    return False

                if not os.path.exists(parent_dir):
                    try:
                        os.makedirs(parent_dir, exist_ok=True)
                        logger.info("Created parent directory: %s", os.path.abspath(parent_dir))
                    except OSError:
                        logger.error("Failed to create parent directory: %s", os.path.abspath(parent_dir), exc_info=True)
                        return False

                with zip_file.open(entry) as in_stream, open(file_path, "wb") as out_stream:
                    while True:
                        chunk = in_stream.read(1024)
                        if not chunk:
                            break
                        out_stream.write(chunk)
                    logger.info("Extracted file: %s", os.path.abspath(file_path))
                return True
        except _IO_ERRORS:
            logger.error("Failed to extract file: %s", file_name, exc_info=True)
            return False
