        if not os.path.exists(self.zip_file_path):
            logger.error("Zip file does not exist: %s", os.path.abspath(self.zip_file_path))
            return None
        try:
            return zipfile.ZipFile(self.zip_file_path, "r")
        except _IO_ERRORS:
            logger.exception("Failed to read the zip file: %s", os.path.abspath(self.zip_file_path))
            return None

    def extract_all(self, output_dir: str) -> bool:
        zip_file = self._read_zip_file()
        if zip_file is None:
            return False
