                                        break
                                    out_stream.write(chunk)
                                logger.info("Extracted file: %s", os.path.abspath(file_path))
                    except _IO_ERRORS:
                        logger.exception("Failed to process entry: %s", entry.filename)
                return True
        except _IO_ERRORS:
            logger.exception("Failed to extract files from zip: %s", os.path.abspath(self.zip_file_path))
            return False

    def extract_file(self, file_name: str, output_dir: str) -> bool:
        file_path = os.path.join(output_dir, file_name)
