#include <charconv>
#include <cmath>
#include <iostream>
#include <string>

namespace {

// Equivalent of Java's Math.PI (the double closest to pi).
constexpr double PI = 3.141592653589793;

// Formats a double the way Java's Double.toString / println does:
// the shortest decimal string that round-trips to the same double.
std::string javaToString(double value) {
    char buffer[32];
    std::to_chars_result result = std::to_chars(buffer, buffer + sizeof(buffer), value);
    std::string s(buffer, result.ptr);
    // Java always keeps at least one fractional digit for finite values
    // printed in decimal form (e.g. "4.0" instead of "4").
    if (s.find('.') == std::string::npos && s.find('e') == std::string::npos) {
        s += ".0";
    }
    return s;
}

}  // namespace

class AreaCalculator {
private:
    double radius;

public:
    explicit AreaCalculator(double radius) : radius(radius) {}

    double calculateCircleArea() const {
        return PI * std::pow(radius, 2);
    }

    double calculateSphereArea() const {
        return 4 * PI * std::pow(radius, 2);
    }

    double calculateCylinderArea(double height) const {
        return 2 * PI * radius * (radius + height);
    }

    double calculateSectorArea(double angle) const {
        return std::pow(radius, 2) * angle / 2;
    }

    double calculateAnnulusArea(double innerRadius, double outerRadius) const {
        return PI * (std::pow(outerRadius, 2) - std::pow(innerRadius, 2));
    }
};

int main() {
    AreaCalculator areaCalculator(2);

    std::cout << "Circle Area: " << javaToString(areaCalculator.calculateCircleArea()) << '\n';
    std::cout << "Sphere Area: " << javaToString(areaCalculator.calculateSphereArea()) << '\n';
    std::cout << "Cylinder Area: " << javaToString(areaCalculator.calculateCylinderArea(3)) << '\n';
    std::cout << "Sector Area: " << javaToString(areaCalculator.calculateSectorArea(PI)) << '\n';
    std::cout << "Annulus Area: " << javaToString(areaCalculator.calculateAnnulusArea(2, 3)) << '\n';

    return 0;
}
```

