namespace org {
namespace example {

class AutomaticGuitarSimulator {
public:
    class ChordTune {
    public:
        ChordTune(std::string chord, std::string tune)
            : chord_(std::move(chord)), tune_(std::move(tune)) {}

        const std::string& getChord() const { return chord_; }
        const std::string& getTune() const { return tune_; }

        bool operator==(const ChordTune& other) const {
            return chord_ == other.chord_ && tune_ == other.tune_;
        }

        bool operator!=(const ChordTune& other) const {
            return !(*this == other);
        }

        // Mirrors Java's hashCode (Java String.hashCode semantics).
        std::int32_t hashCode() const {
            std::int32_t result = javaStringHashCode(chord_);
            result = wrap31(result, javaStringHashCode(tune_));
            return result;
        }

    private:
        std::string chord_;
        std::string tune_;

        static std::int32_t javaStringHashCode(const std::string& s) {
            std::int32_t h = 0;
            for (unsigned char c : s) {
                h = wrap31(h, static_cast<std::int32_t>(c));
            }
            return h;
        }

        static std::int32_t wrap31(std::int32_t acc, std::int32_t add) {
            return static_cast<std::int32_t>(
                31u * static_cast<std::uint32_t>(acc) + static_cast<std::uint32_t>(add));
        }
    };

    explicit AutomaticGuitarSimulator(std::string text)
        : playText_(std::move(text)) {}

    std::optional<std::vector<ChordTune>> interpret(bool display) {
        if (javaTrim(playText_).empty()) {
            return std::nullopt;
        }

        std::vector<ChordTune> playList;
        std::vector<std::string> playSegs = splitOnSpace(playText_);
        for (const std::string& playSeg : playSegs) {
            if (javaTrim(playSeg).empty()) {
                continue;
            }
            std::size_t pos = 0;
            for (char ele : playSeg) {
                if (std::isalpha(static_cast<unsigned char>(ele))) {
                    ++pos;
                    continue;
                }
                break;
            }
            std::string playChord = playSeg.substr(0, pos);
            std::string playValue = playSeg.substr(pos);
            playList.emplace_back(playChord, playValue);
            if (display) {
                this->display(playChord, playValue);
            }
        }
        return playList;
    }

    std::string display(const std::string& key, const std::string& value) {
        std::ostringstream oss;
        oss << "Normal Guitar Playing -- Chord: " << key
            << ", Play Tune: " << value;
        return oss.str();
    }

private:
    std::string playText_;

    // Equivalent of Java's String.trim() check (chars <= ' ' are whitespace).
    static std::string javaTrim(const std::string& s) {
        std::size_t begin = 0;
        std::size_t end = s.size();
        while (begin < end && static_cast<unsigned char>(s[begin]) <= 0x20) {
            ++begin;
        }
        while (end > begin && static_cast<unsigned char>(s[end - 1]) <= 0x20) {
            --end;
        }
        return s.substr(begin, end - begin);
    }

    // Equivalent of Java's playText.split(" "): split on every single space.
    static std::vector<std::string> splitOnSpace(const std::string& text) {
        std::vector<std::string> parts;
        std::string current;
        for (char c : text) {
            if (c == ' ') {
                parts.push_back(current);
                current.clear();
            } else {
                current.push_back(c);
            }
        }
        parts.push_back(current);
        return parts;
    }
};

}  // namespace example
}  // namespace org
```

