static std::string javaDoubleToString(double d) {
    if (std::isnan(d)) return "NaN";
    if (std::isinf(d)) return d > 0 ? "Infinity" : "-Infinity";
    bool neg = std::signbit(d);
    double a = std::fabs(d);
    if (a == 0.0) return neg ? "-0.0" : "0.0";
    char buf[64];
    auto res = std::to_chars(buf, buf + sizeof(buf), a, std::chars_format::scientific);
    std::string sci(buf, res.ptr);
    size_t ePos = sci.find('e');
    std::string mantissa = sci.substr(0, ePos);
    int exp10 = std::atoi(sci.c_str() + ePos + 1);
    std::string digits = mantissa;
    size_t dot = digits.find('.');
    if (dot != std::string::npos) digits.erase(dot, 1);
    int n = exp10 + 1; // digits before the decimal point in plain notation
    std::string body;
    if (n >= -2 && n <= 7) {
        if (n <= 0) {
            body = "0.";
            body.append(-n, '0');
            body += digits;
        } else if (static_cast<size_t>(n) >= digits.size()) {
            body = digits;
            body.append(static_cast<size_t>(n) - digits.size(), '0');
            body += ".0";
        } else {
            body = digits.substr(0, static_cast<size_t>(n));
            body += '.';
            body += digits.substr(static_cast<size_t>(n));
        }
    } else {
        body = digits.substr(0, 1);
        body += '.';
        body += (digits.size() > 1) ? digits.substr(1) : std::string("0");
        body += 'E';
        body += std::to_string(n - 1);
    }
    return (neg ? "-" : "") + body;
}
