#include <cmath>
#include <cerrno>
#include <cstdlib>
#include <functional>
#include <iostream>
#include <optional>
#include <stack>
#include <stdexcept>
#include <string>
#include <unordered_map>

namespace org::example {

class Calculator {
private:
    using Operation = std::function<double(double, double)>;
    std::unordered_map<char, Operation> operators;

public:
    Calculator() {
        operators.emplace('+', [](double x, double y) { return x + y; });
        operators.emplace('-', [](double x, double y) { return x - y; });
        operators.emplace('*', [](double x, double y) { return x * y; });
        operators.emplace('/', [](double x, double y) { return x / y; });
        operators.emplace('^', [](double x, double y) { return std::pow(x, y); });
    }

    std::optional<double> calculate(const std::string& expression) {
        std::stack<double> operandStack;
        std::stack<char> operatorStack;
        std::string numBuffer;

        for (std::size_t i = 0; i < expression.size(); ++i) {
            char ch = expression[i];
            if (std::isdigit(static_cast<unsigned char>(ch)) || ch == '.') {
                numBuffer += ch;
            } else {
                if (!numBuffer.empty()) {
                    operandStack.push(parseDouble(numBuffer));
                    numBuffer.clear();
                }

                if (operators.find(ch) != operators.end()) {
                    while (!operatorStack.empty() &&
                           operatorStack.top() != '(' &&
                           precedence(operatorStack.top()) >= precedence(ch)) {
                        applyOperator(operandStack, operatorStack);
                    }
                    operatorStack.push(ch);
                } else if (ch == '(') {
                    operatorStack.push(ch);
                } else if (ch == ')') {
                    while (!operatorStack.empty() && operatorStack.top() != '(') {
                        applyOperator(operandStack, operatorStack);
                    }
                    operatorStack.pop(); // EmptyStackException if empty, like Java
                }
            }
        }

        if (!numBuffer.empty()) {
            operandStack.push(parseDouble(numBuffer));
        }

        while (!operatorStack.empty()) {
            applyOperator(operandStack, operatorStack);
        }

        return operandStack.empty() ? std::nullopt : std::optional<double>(operandStack.top());
    }

private:
    int precedence(char op) const {
        switch (op) {
            case '+':
            case '-':
                return 1;
            case '*':
            case '/':
                return 2;
            case '^':
                return 3;
            default:
                return 0;
        }
    }

    void applyOperator(std::stack<double>& operandStack, std::stack<char>& operatorStack) {
        char op = popTop(operatorStack);
