class BinaryDataProcessor {
private:
    std::string binaryString;

public:
    explicit BinaryDataProcessor(const std::string& binaryString)
        : binaryString(binaryString) {
        cleanNonBinaryChars();
    }

    void cleanNonBinaryChars() {
        std::string cleaned;
        cleaned.reserve(binaryString.size());
        for (char c : binaryString) {
            if (c == '0' || c == '1') {
                cleaned += c;
            }
        }
        binaryString = cleaned;
    }

    BinaryInfo calculateBinaryInfo() const {
        int totalLength = static_cast<int>(binaryString.length());
        int zeroesCount = 0;
        int onesCount = 0;
        for (char c : binaryString) {
            if (c == '0') {
                ++zeroesCount;
            } else if (c == '1') {
                ++onesCount;
            }
        }
        double zeroesPercentage = static_cast<double>(zeroesCount) / totalLength;
        double onesPercentage = static_cast<double>(onesCount) / totalLength;
        return BinaryInfo(zeroesPercentage, onesPercentage, totalLength);
    }

    std::string convertToAscii() const {
        std::string asciiString;
        for (std::size_t i = 0; i < binaryString.length(); i += 8) {
            std::string byteString = substring(i, i + 8);
            int decimal = std::stoi(byteString, nullptr, 2);
            asciiString += static_cast<char>(decimal);
        }
        return asciiString;
    }

    std::string convertToUtf8() const {
        std::string utf8String;
        for (std::size_t i = 0; i < binaryString.length(); i += 8) {
            std::string byteString = substring(i, i + 8);
            int decimal = std::stoi(byteString, nullptr, 2);
            utf8String += static_cast<char>(decimal);
        }
        return utf8String;
    }

    const std::string& getBinaryString() const {
        return binaryString;
    }

private:
    // Mimics Java's String.substring(begin, end), which throws when
    // end exceeds the string length (unlike std::string::substr, which clamps).
    std::string substring(std::size_t begin, std::size_t end) const {
        if (end > binaryString.length()) {
            throw std::out_of_range("String index out of range: " + std::to_string(end));
        }
        return binaryString.substr(begin, end - begin);
    }
};
```

