static Ymd parseIsoDate(const std::string& s) {
    auto fail = [&]() { throw std::runtime_error("Invalid date: '" + s + "'"); };
    if (s.size() != 10 || s[4] != '-' || s[7] != '-') fail();
    for (std::size_t i = 0; i < s.size(); ++i) {
        if (i == 4 || i == 7) continue;
