public:
    class Message {
    public:
        Message(std::string sender, std::string receiver, std::string message, std::string timestamp)
            : sender_(std::move(sender)),
              receiver_(std::move(receiver)),
              message_(std::move(message)),
              timestamp_(std::move(timestamp)) {}

        const std::string& getSender() const { return sender_; }
        const std::string& getReceiver() const { return receiver_; }
        const std::string& getMessage() const { return message_; }
        const std::string& getTimestamp() const { return timestamp_; }

        bool operator==(const Message& other) const {
            return sender_ == other.sender_ && receiver_ == other.receiver_ &&
                   message_ == other.message_ && timestamp_ == other.timestamp_;
        }

        bool operator!=(const Message& other) const { return !(*this == other); }

        std::string toString() const {
            std::ostringstream oss;
            oss << *this;
            return oss.str();
        }

        friend std::ostream& operator<<(std::ostream& os, const Message& message) {
            os << "Message{sender='" << message.sender_
               << "', receiver='" << message.receiver_
               << "', message='" << message.message_
               << "', timestamp='" << message.timestamp_ << "'}";
            return os;
        }

    private:
        std::string sender_;
        std::string receiver_;
        std::string message_;
        std::string timestamp_;
    };

    Chat() = default;

    bool addUser(const std::string& username) {
        if (users.find(username) != users.end()) {
            return false;
        }
        users.emplace(username, std::vector<Message>());
        return true;
    }

    bool removeUser(const std::string& username) {
        return users.erase(username) > 0;
    }

    bool sendMessage(const std::string& sender, const std::string& receiver, const std::string& message) {
        auto senderIt = users.find(sender);
        if (senderIt == users.end()) {
            return false;
        }
        auto receiverIt = users.find(receiver);
        if (receiverIt == users.end()) {
            return false;
        }

        std::string timestamp = currentTimestamp();

        Message messageInfo(sender, receiver, message, timestamp);

        senderIt->second.push_back(messageInfo);
        receiverIt->second.push_back(messageInfo);
        return true;
    }

    std::vector<Message>& getMessages(const std::string& username) {
        auto it = users.find(username);
        if (it == users.end()) {
            static std::vector<Message> empty;
            empty.clear();  // emulate returning a fresh empty list
            return empty;
        }
        return it->second;
    }

    const std::vector<Message>& getMessages(const std::string& username) const {
        auto it = users.find(username);
        if (it == users.end()) {
            static const std::vector<Message> empty;
            return empty;
        }
        return it->second;
    }

    std::unordered_map<std::string, std::vector<Message>>& getUsers() { return users; }
    const std::unordered_map<std::string, std::vector<Message>>& getUsers() const { return users; }

private:
    static std::string currentTimestamp() {
        std::time_t now = std::time(nullptr);
        std::tm localTime{};
#ifdef _MSC_VER
        localtime_s(&localTime, &now);
#else
        localtime_r(&now, &localTime);
#endif
        std::ostringstream oss;
        oss << std::put_time(&localTime, "%Y-%m-%d %H:%M:%S");
        return oss.str();
    }

    std::unordered_map<std::string, std::vector<Message>> users;
};

