static LocalTime parse(const std::string& text) {
    const std::size_t len = text.length();

    auto isDigit = [](char c) { return c >= '0' && c <= '9'; };
    auto fail = [&text](const std::string& detail) -> LocalTime {
        throw DateTimeParseException(
            "Text '" + text + "' could not be parsed" +
            (detail.empty() ? std::string() : ": " + detail));
    };

    // Minimum "HH:mm"
    if (len < 5) fail("");
    if (!isDigit(text[0]) || !isDigit(text[1]) || text[2] != ':' ||
        !isDigit(text[3]) || !isDigit(text[4])) {
        fail("");
    }

    const int hour = (text[0] - '0') * 10 + (text[1] - '0');
    const int minute = (text[3] - '0') * 10 + (text[4] - '0');

    int second = 0;
    int nano = 0;

    if (len > 5) {
        if (len < 8 || text[5] != ':' || !isDigit(text[6]) || !isDigit(text[7])) {
            fail("");
        }
        second = (text[6] - '0') * 10 + (text[7] - '0');

        if (len > 8) {
            if (text[8] != '.') fail("");
            const std::size_t fracStart = 9;
            std::size_t fracEnd = fracStart;
            while (fracEnd < len && isDigit(text[fracEnd])) ++fracEnd;
            const std::size_t digitCount = fracEnd - fracStart;
            if (digitCount < 1 || digitCount > 9 || fracEnd != len) {
                fail("");
            }
            long long value = 0;
            for (std::size_t i = fracStart; i < fracEnd; ++i) {
                value = value * 10 + (text[i] - '0');
            }
            for (std::size_t i = digitCount; i < 9; ++i) value *= 10;
            nano = static_cast<int>(value);
        }
    }

    if (hour > 23) fail("Invalid value for HourOfDay (valid values 0 - 23): " + std::to_string(hour));
    if (minute > 59) fail("Invalid value for MinuteOfHour (valid values 0 - 59): " + std::to_string(minute));
    if (second > 59) fail("Invalid value for SecondOfMinute (valid values 0 - 59): " + std::to_string(second));

    return LocalTime(hour, minute, second, nano);
}
