namespace org {
namespace example {

// Equivalent of java.time.format.DateTimeParseException.
class DateTimeParseException : public std::runtime_error {
public:
    explicit DateTimeParseException(const std::string& message)
        : std::runtime_error(message) {}
};

// Equivalent of java.time.LocalTime (only the API used here is implemented).
// Immutable value type; parsing follows the ISO local time format HH:mm[:ss[.f{1,9}]].
class LocalTime {
public:
    LocalTime() : hour_(0), minute_(0), second_(0), nano_(0) {}

    static LocalTime parse(const std::string& text) {
        const std::size_t len = text.length();
        const auto isDigit = [](char c) { return c >= '0' && c <= '9'; };
        const auto fail = [&text](const std::string& detail) -> LocalTime {
            throw DateTimeParseException(
                "Text '" + text + "' could not be parsed" +
                (detail.empty() ? std::string() : ": " + detail));
        };

        if (len < 5) fail(std::string());
        if (!isDigit(text[0]) || !isDigit(text[1]) || text[2] != ':' ||
            !isDigit(text[3]) || !isDigit(text[4])) {
            fail(std::string());
        }

        const int hour = (text[0] - '0') * 10 + (text[1] - '0');
        const int minute = (text[3] - '0') * 10 + (text[4] - '0');
        int second = 0;
        int nano = 0;

        if (len > 5) {
            if (len < 8 || text[5] != ':' || !isDigit(text[6]) || !isDigit(text[7])) {
                fail(std::string());
            }
            second = (text[6] - '0') * 10 + (text[7] - '0');

            if (len > 8) {
                if (text[8] != '.') fail(std::string());
                std::size_t fracEnd = 9;
                while (fracEnd < len && isDigit(text[fracEnd])) ++fracEnd;
                const std::size_t digitCount = fracEnd - 9;
                if (digitCount < 1 || digitCount > 9 || fracEnd != len) {
                    fail(std::string());
                }
                long long value = 0;
                for (std::size_t i = 9; i < fracEnd; ++i) {
                    value = value * 10 + (text[i] - '0');
                }
                for (std::size_t i = digitCount; i < 9; ++i) value *= 10;
                nano = static_cast<int>(value);
            }
        }

        if (hour > 23) {
            fail("Invalid value for HourOfDay (valid values 0 - 23): " + std::to_string(hour));
        }
        if (minute > 59) {
            fail("Invalid value for MinuteOfHour (valid values 0 - 59): " + std::to_string(minute));
        }
        if (second > 59) {
            fail("Invalid value for SecondOfMinute (valid values 0 - 59): " + std::to_string(second));
        }

        return LocalTime(hour, minute, second, nano);
    }

    bool isBefore(const LocalTime& other) const { return compare(other) < 0; }
    bool isAfter(const LocalTime& other) const { return compare(other) > 0; }

    bool operator==(const LocalTime& other) const { return compare(other) == 0; }
    bool operator!=(const LocalTime& other) const { return compare(other) != 0; }

private:
    LocalTime(int hour, int minute, int second, int nano)
        : hour_(hour), minute_(minute), second_(second), nano_(nano) {}

    int compare(const LocalTime& other) const {
        if (hour_ != other.hour_) return hour_ < other.hour_ ? -1 : 1;
        if (minute_ != other.minute_) return minute_ < other.minute_ ? -1 : 1;
        if (second_ != other.second_) return second_ < other.second_ ? -1 : 1;
        if (nano_ != other.nano_) return nano_ < other.nano_ ? -1 : 1;
        return 0;
    }

    int hour_;
    int minute_;
    int second_;
    int nano_;
};

