```cpp
static int doubleCompare(double a, double b) {
    if (std::isnan(a)) return std::isnan(b) ? 0 : 1;
    if (std::isnan(b)) return -1;
    if (a == b) {
        // +0.0 vs -0.0
        bool na = std::signbit(a), nb = std::signbit(b);
        if (na == nb) return 0;
        return na ? -1 : 1; // -0.0 < +0.0
    }
    return a < b ? -1 : 1;
}
