   class JsonParser {
   public:
       explicit JsonParser(const std::string& input) : input_(input), pos_(0) {}

       JsonValue parse() {
           JsonValue v = parseValue();
           skipWhitespace();
           if (pos_ != input_.size()) throw JsonParseException("Unexpected token at position " + std::to_string(pos_));
           return v;
       }

   private:
       const std::string& input_;
       size_t pos_;

       void skipWhitespace() {
           while (pos_ < input_.size()) {
               char c = input_[pos_];
               if (c == ' ' || c == '\t' || c == '\n' || c == '\r') ++pos_;
               else break;
           }
       }

       char peek() {
           if (pos_ >= input_.size()) throw JsonParseException("Unexpected end of input");
           return input_[pos_];
       }

       char next() {
           char c = peek();
           ++pos_;
           return c;
       }

       JsonValue parseValue() {
           skipWhitespace();
           char c = peek();
           switch (c) {
               case '{': return parseObject();
               case '[': return parseArray();
               case '"': { JsonValue v; v.type = Type::String; v.text = parseString(); return v; }
               case 't': case 'f': return parseBoolean();
               case 'n': return parseNull();
               default:
                   if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
                   throw JsonParseException("Unexpected token");
           }
       }
       ...
   };
