   ```cpp
   unsigned parseHex4() {
       unsigned value = 0;
       for (int i = 0; i < 4; ++i) {
           char c = next();
           unsigned d;
           if (c >= '0' && c <= '9') d = c - '0';
           else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
           else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
           else throw JsonParseException("Invalid unicode escape");
           value = (value << 4) | d;
       }
       return value;
   }
