       size_t start = pos_;
       if (peek() == '-') ++pos_;
       // integer part
       if (pos_ >= input_.size()) throw ...;
       char c = input_[pos_];
       if (c == '0') { ++pos_; }
       else if (c >= '1' && c <= '9') { while (pos_ < size && isdigit) ++pos_; }
       else throw JsonParseException("Invalid number");
       // fraction
       if (pos_ < size && input_[pos_] == '.') {
           ++pos_;
           if (no digits) throw;
           consume digits;
       }
       // exponent
       if (pos_ < size && (input_[pos_]=='e'||'E')) {
           ++pos_;
           if ('+'||'-') ++pos_;
           if (no digits) throw;
           consume digits;
       }
       v.text = input_.substr(start, pos_ - start);
       return v;
   }
